async function api(path, method = 'GET', data, extraHeaders = {}) {
  const headers = { 'X-Central-Request': '1', ...extraHeaders }
  const body = data instanceof FormData ? data : data === undefined ? undefined : (headers['Content-Type'] = 'application/json', JSON.stringify(data))
  const response = await fetch(`/api${path}`, { method, headers, body, credentials: 'same-origin' })
  let result
  try { result = await response.json() } catch { result = { detail: 'Resposta inválida do servidor.' } }
  if (!response.ok) throw new Error(typeof result.detail === 'string' ? result.detail : JSON.stringify(result.detail || 'Ocorreu um erro.'))
  return result
}

function dateLabel(value, detailed = false) {
  if (!value) return '—'
  return new Date(value).toLocaleString('pt-BR', detailed ? { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' } : { day: '2-digit', month: 'short' })
}

function Icon({ children, className = '' }) { return <span aria-hidden="true" className={`inline-grid w-5 shrink-0 place-items-center text-[16px] ${className}`}>{children}</span> }
function Button({ children, primary = false, quiet = false, small = false, danger = false, className = '', ...props }) {
  return <button {...props} className={`inline-flex items-center justify-center gap-2 rounded-xl border px-4 font-medium transition duration-150 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-aqua disabled:pointer-events-none disabled:opacity-50 ${small ? 'min-h-8 px-3 text-xs' : 'min-h-10 text-sm'} ${primary ? 'border-transparent bg-gradient-to-r from-[#4285f4] via-[#9b72cb] to-[#d96570] text-white shadow-lg shadow-violet-950/20 hover:brightness-110' : danger ? 'border-rose-400/25 bg-rose-400/5 text-rose-300 hover:bg-rose-400/10' : quiet ? 'border-transparent bg-transparent text-muted hover:bg-white/[.06] hover:text-copy' : 'border-white/10 bg-white/[.045] text-copy hover:border-lilac/40 hover:bg-white/[.08]'} ${className}`}>{children}</button>
}
function BrandOrbit({ className = '' }) {
  const src = import.meta.env.PROD ? '/assets/build/logos/02-orbita.svg' : '/logos/02-orbita.svg'
  return <img src={src} alt="" aria-hidden="true" className={'brand-orbit ' + className} />
}
function Status({ value, children }) {
  const colors = value === 'completed' || value === 'healthy' ? 'border-emerald-300/15 bg-emerald-300/10 text-emerald-200' : value === 'failed' || value === 'cancelled' || value === 'suspended' ? 'border-rose-300/15 bg-rose-300/10 text-rose-200' : value === 'running' || value === 'queued' || value === 'awaiting_approval' || value === 'degraded' || value === 'recovering' ? 'border-violet-300/15 bg-violet-300/10 text-violet-200' : 'border-white/10 bg-white/5 text-muted'
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] ${colors}`}><span className="h-1.5 w-1.5 rounded-full bg-current opacity-80" />{children || statusNames[value] || value || 'Sem medições'}</span>
}
