function RichText({ text }) {
  const blocks = String(text || '').split(/```/g)
  return <div className="space-y-2 text-[13px] leading-7 text-copy">{blocks.map((block, i) => i % 2 ? <pre key={i} className="overflow-x-auto rounded-xl border border-white/10 bg-[#121214] p-4 text-xs leading-6 text-aqua"><code>{block.replace(/^[\w+#.-]+\n/, '')}</code></pre> : block.split('\n').filter(line => line.trim()).map((line, j) => {
    if (line.startsWith('### ')) return <h3 key={`${i}-${j}`} className="pt-3 text-base font-semibold">{line.slice(4)}</h3>
    if (line.startsWith('## ')) return <h3 key={`${i}-${j}`} className="pt-3 text-lg font-semibold">{line.slice(3)}</h3>
    const parts = line.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)
    return <p key={`${i}-${j}`}>{/^[-*] /.test(line) && <span className="mr-2 text-lilac">•</span>}{parts.map((part,k) => part.startsWith('**') ? <strong key={k}>{part.slice(2,-2)}</strong> : part.startsWith('`') ? <code key={k} className="rounded bg-white/10 px-1.5 py-0.5 text-aqua">{part.slice(1,-1)}</code> : part.replace(/^[-*] /,''))}</p>
  }))}</div>
}

function ChatPage({ data, messages, steps, mode, setMode, selectedAgent, setSelectedAgent, prompt, setPrompt, files, setFiles, running, onSend, onCancel, onApproval, onSuggest, currentConvo, selectedProject, onOpenMemory, onMenu, onCommand }) {
  const fileRef = useRef(null)
  const transcriptRef = useRef(null)
  const [activeCommand, setActiveCommand] = useState(0)
  const matchingCommands = prompt.startsWith('/')
    ? chatCommands.filter(item => item.command.startsWith(prompt.trim().toLowerCase()) || item.label.toLowerCase().includes(prompt.trim().slice(1).toLowerCase()))
    : []
  useEffect(() => { if (transcriptRef.current) transcriptRef.current.scrollTop = transcriptRef.current.scrollHeight }, [messages, steps])
  async function attach(e) {
    const file = e.target.files?.[0]
    if (!file) return
    const form = new FormData()
    form.append('file', file)
    try {
      const uploaded = await api('/uploads/text', 'POST', form)
      setFiles(items => [...items, uploaded])
    } catch (error) {
      window.dispatchEvent(new CustomEvent('app-toast', { detail: error.message }))
    }
    e.target.value = ''
  }
  function handleKeyDown(e) {
    if (e.key === 'Escape') {
      if (matchingCommands.length) { e.preventDefault(); setPrompt('') }
      return
    }
    if (matchingCommands.length && e.key === 'ArrowDown') { e.preventDefault(); setActiveCommand(index => (index + 1) % matchingCommands.length); return }
    if (matchingCommands.length && e.key === 'ArrowUp') { e.preventDefault(); setActiveCommand(index => (index - 1 + matchingCommands.length) % matchingCommands.length); return }
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      if (matchingCommands.length) onCommand(matchingCommands[Math.min(activeCommand, matchingCommands.length - 1)].command)
      else onSend()
    }
  }
  const activeProject = data.projects.find(p => p.id === (data.conversations.find(c => c.id === currentConvo)?.project_id || selectedProject))
  return <div className="relative flex h-full min-h-0 flex-col">
    <header className="flex min-h-[62px] shrink-0 items-center justify-between gap-3 border-b border-white/[.07] px-5 py-2 max-sm:px-3">
      <div className="min-w-0"><strong className="block truncate text-[13px] font-semibold">{data.conversations.find(c => c.id === currentConvo)?.title || 'Nova conversa'}</strong><small className="mt-1 block text-[11px] text-muted">{activeProject ? '▤ ' + activeProject.name + ' · memória ampliada' : 'Conversa avulsa · memória curta'}</small></div>
      <div className="flex flex-wrap items-center justify-end gap-2">
        <button type="button" onClick={onOpenMemory} title="Buscar conversas e configurar memória" className="rounded-xl border border-lilac/30 px-3 py-2 text-[11px] text-lilac hover:bg-lilac/10">⌕ Memória</button>
        <select value={mode} onChange={e => setMode(e.target.value)} aria-label="Modo de trabalho" className="max-w-[150px] rounded-xl border border-white/10 bg-card px-3 py-2 text-[11px] text-copy outline-none focus:border-lilac/50"><option value="auto">✦ Automático</option><option value="manual">◇ Um trabalhador</option><option value="team">▣ Equipe</option></select>
        <select value={selectedAgent} onChange={e => { setSelectedAgent(e.target.value); setMode(e.target.value ? 'manual' : 'auto') }} aria-label="Trabalhador preferido" className="max-w-[155px] rounded-xl border border-white/10 bg-card px-3 py-2 text-[11px] text-copy outline-none focus:border-lilac/50"><option value="">Qualquer trabalhador</option>{data.agents.filter(a => a.enabled).map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
      </div>
    </header>
    <div ref={transcriptRef} className="scrollbar-soft relative min-h-0 flex-1 overflow-y-auto px-6 py-5 max-sm:px-3">
      {!messages.length ? <ChatWelcome onSuggest={onSuggest} /> : <div className="mx-auto max-w-3xl py-5">{messages.map((message, index) => message.type === 'event' ? <div key={index} className="my-3 rounded-xl border border-lilac/15 bg-lilac/5 px-4 py-2 text-xs text-violet-100">{message.content}</div> : <article key={message.stepId || index} className={'mb-7 flex gap-3 ' + (message.role === 'user' ? 'flex-row-reverse' : '')}><div className={'grid h-8 w-8 shrink-0 place-items-center rounded-full text-sm text-white ' + (message.role === 'user' ? 'bg-[#36363c]' : 'bg-gradient-to-br from-[#8670d4] to-[#4a8da0]')}>{message.role === 'user' ? '☺' : <BrandOrbit className="h-6 w-6"/>}</div><div className={'min-w-0 ' + (message.role === 'user' ? 'max-w-[78%]' : '')}><p className="mb-2 text-xs font-semibold text-copy">{message.role === 'user' ? 'Você' : message.agent || 'Central IA'}</p>{message.role === 'user' ? <div className="rounded-[17px] rounded-tr-[5px] border border-white/10 bg-white/[.07] px-4 py-3 text-sm leading-6">{message.content}</div> : <RichText text={message.content} />}</div></article>)}</div>}
      {steps.length > 0 && <section aria-live="polite" className="mx-auto mb-5 max-w-3xl rounded-2xl border border-white/10 bg-white/[.035] p-4">
        <div className="mb-3 flex items-center justify-between"><strong className="text-xs font-semibold">Etapas da execução</strong><span className="text-[10px] text-muted">{steps.filter(step => step.status === 'completed').length}/{steps.length} concluídas</span></div>
        <div className="space-y-2">{steps.map(step => <div key={step.id} className="rounded-xl border border-white/[.07] bg-black/10 p-3">
          <div className="flex flex-wrap items-center justify-between gap-2"><span className="text-xs text-copy">{step.name}</span><Status value={step.status}>{statusNames[step.status] || step.status}</Status></div>
          {step.model && <p className="mt-1 text-[10px] text-muted">{step.provider ? step.provider + ' · ' : ''}{step.model}</p>}
          {step.status === 'awaiting_approval' && <div className="mt-3 rounded-xl border border-amber-300/20 bg-amber-300/[.06] p-3"><p className="text-xs leading-5 text-copy">Esta etapa está aguardando sua autorização. Deseja permitir que o trabalhador <strong>{step.name}</strong> continue?</p><div className="mt-3 flex flex-wrap gap-2"><Button small primary onClick={() => onApproval(step.id, true)}>Aprovar</Button><Button small onClick={() => onApproval(step.id, false)}>Negar</Button><span className="self-center text-[10px] text-muted">ou use /aprovar e /rejeitar</span></div></div>}
        </div>)}</div>
      </section>}
    </div>
    <div className="shrink-0 border-t border-white/[.06] px-6 pb-4 pt-4 max-sm:px-3">
      <div className="relative mx-auto max-w-[690px]">
        {matchingCommands.length > 0 && <div role="listbox" aria-label="Comandos" className="absolute bottom-[calc(100%+9px)] left-0 right-0 z-30 overflow-hidden rounded-2xl border border-white/10 bg-[#202024] p-1.5 shadow-2xl shadow-black/50">
          {matchingCommands.map(item => <button key={item.command} type="button" role="option" onClick={() => onCommand(item.command)} className={'flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left ' + (matchingCommands[Math.min(activeCommand, matchingCommands.length - 1)]?.command === item.command ? 'bg-white/[.07]' : 'hover:bg-white/[.07]')}><code className="min-w-28 text-xs font-semibold text-lilac">{item.command}</code><span className="min-w-0"><strong className="block text-xs font-medium text-copy">{item.label}</strong><small className="text-[10px] text-muted">{item.description}</small></span></button>)}
        </div>}
        <div className={"chat-composer rounded-[23px] shadow-xl shadow-black/15 focus-within:ring-4 focus-within:ring-lilac/5 " + (prompt.trim() ? "is-typing" : "")}>
          <textarea value={prompt} onChange={e => { setPrompt(e.target.value); setActiveCommand(0) }} onKeyDown={handleKeyDown} rows={2} placeholder="Escreva uma mensagem ou digite / para ver comandos..." className="block max-h-40 min-h-[67px] w-full resize-y bg-transparent px-5 pt-4 text-sm text-copy outline-none placeholder:text-[#aaa7b1]" />
          <div className="flex flex-wrap items-center justify-between gap-2 px-3 pb-3"><div className="flex min-w-0 items-center gap-2"><input ref={fileRef} type="file" className="hidden" accept=".txt,.md,.csv,.json,.py,.ts,.tsx,.jsx,.js,.html,.css,.sql,.yaml,.yml,.xml" onChange={attach} /><Button small quiet onClick={() => fileRef.current?.click()}>＋ Anexar</Button><span className="truncate text-[10px] text-muted">{files.length ? files.map(f => f.name).join(', ') : 'Até 2 MB'}</span></div><div className="flex items-center gap-2">{running && <Button small quiet onClick={onCancel}>■ Parar</Button>}<Button primary small onClick={() => matchingCommands.length ? onCommand(matchingCommands[Math.min(activeCommand, matchingCommands.length - 1)].command) : onSend()} disabled={!prompt.trim() || running}>{running ? 'Executando…' : matchingCommands.length ? 'Executar comando' : <>Enviar <span aria-hidden="true">↑</span></>}</Button></div></div>
        </div>
      </div>
      <p className="mx-auto mt-2 max-w-[690px] text-center text-[10px] text-muted">Tarefas usam suas próprias chaves de provedor e podem gerar cobranças.</p>
    </div>
  </div>
}

function Dashboard({ data, stats, page, navigate, onHistory }) {
  if (!stats) return <div className="grid min-h-64 place-items-center text-sm text-muted">Carregando…</div>
  const cards = [[ 'Trabalhadores disponíveis', stats.agents, '◈', 'Agentes ativos' ], ['Tarefas concluídas',stats.completed,'✓','Execuções finalizadas'],['Em execução',stats.running+stats.queued,'⌁',`${stats.queued} na fila`],['Recuperações acionadas',stats.failovers,'↻','Eventos de failover']]
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow={page==='monitoring'?'OBSERVABILIDADE':'VISÃO GERAL'} title={page==='monitoring'?'Monitoramento em tempo real':'Seu centro de operações'} description={page==='monitoring'?'Dados reais coletados durante suas execuções.':'Gerencie seus trabalhadores, acompanhe tarefas e conecte suas melhores IAs.'} action={<Button primary onClick={()=>navigate('chat')}>✦ Nova tarefa <span>→</span></Button>} />{page!=='monitoring'&&<section className="relative mb-5 overflow-hidden rounded-3xl border border-white/10 bg-gradient-to-br from-[#22242c] via-[#27213a] to-[#1d2833] p-8 max-sm:p-6"><div className="pointer-events-none absolute -right-8 -top-28 h-72 w-72 rounded-full bg-violet-400/10 blur-[70px]" /><p className="relative text-[10px] font-bold tracking-[.16em] text-lilac">✧ SEU WORKSPACE, MAIS INTELIGENTE</p><h2 className="relative mt-3 text-2xl font-semibold tracking-tight">Uma equipe inteira de IA.<br />Um só lugar para criar.</h2><p className="relative mt-3 max-w-xl text-sm leading-6 text-[#c0bdc8]">Distribua tarefas entre especialistas, execute em paralelo e alterne modelos automaticamente quando necessário.</p><Button primary small className="relative mt-5" onClick={()=>navigate('chat')}>Começar agora →</Button></section>}{!data.providers.some(p=>p.enabled)&&<div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-amber-300/15 bg-amber-300/[.05] p-4 text-sm text-[#dccba5]">Nenhum modelo conectado. Configure um provedor para executar tarefas.<Button small onClick={()=>navigate('providers')}>Configurar provedor →</Button></div>}<div className="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4">{cards.map(([label,value,glyph,foot])=><article key={label} className="rounded-2xl border border-white/[.09] bg-panel p-5"><div className="flex items-center justify-between text-xs text-muted"><span>{label}</span><span className="text-lg text-lilac">{glyph}</span></div><p className="mt-3 text-3xl font-semibold tracking-tight">{value}</p><p className="mt-1 text-[11px] text-muted">{foot}</p></article>)}</div><div className="grid gap-4 xl:grid-cols-[1.45fr_1fr]"><Panel title="Atividade recente" action={<Button quiet small onClick={()=>navigate('history')}>Ver histórico →</Button>}>{stats.recent?.length?<div className="divide-y divide-white/[.07] px-5">{stats.recent.map(run=><div key={run.id} className="flex items-center justify-between gap-4 py-4"><span className="min-w-0"><strong className="block truncate text-xs font-medium">{run.prompt}</strong><small className="mt-1 block text-[10px] text-muted">{dateLabel(run.created_at,true)}</small></span><Status value={run.status}/></div>)}</div>:<Empty title="Nenhuma execução ainda">Suas tarefas aparecerão aqui.</Empty>}</Panel><Panel title="Provedores conectados" action={<Button quiet small onClick={()=>navigate('providers')}>Gerenciar →</Button>}>{data.providers.length?data.providers.map(provider=><div key={provider.id} className="mx-5 flex items-center gap-3 border-t border-white/[.07] py-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-lilac/10 text-lilac">⬡</span><span className="min-w-0 flex-1"><strong className="block truncate text-xs">{provider.name}</strong><small className="block truncate text-[10px] text-muted">{provider.model}</small></span><Status value={provider.enabled?'completed':'failed'}>{provider.enabled?'Ativo':'Inativo'}</Status></div>):<Empty icon="⬡" title="Conecte sua primeira IA">OpenAI, Claude, Gemini, DeepSeek e mais.</Empty>}</Panel></div>{page==='monitoring'&&<HealthPanel data={data} onHistory={onHistory} />}</div>
}

function HealthPanel({ data, onHistory }) {
  const [entries,setEntries]=useState(null);const [provider,setProvider]=useState(null)
  const stateFor=p=>{if(!p.enabled)return ['Pausado','failed'];const states={healthy:['Saudável','completed'],degraded:['Instável','running'],suspended:['Suspenso','failed'],recovering:['Em recuperação','running'],untested:['Sem medições','']};return states[p.health?.state]||['Sem medições','']}
  return <section className="mt-5 overflow-hidden rounded-2xl border border-white/[.09] bg-panel"><div className="flex items-center justify-between px-5 py-4"><h2 className="text-sm font-semibold">Saúde e disponibilidade das conexões</h2><Button small onClick={()=>window.location.reload()}>↻ Atualizar</Button></div>{data.providers.length?<div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-xs"><thead className="bg-white/[.035] text-[10px] uppercase tracking-wider text-muted"><tr>{['Conexão / modelo','Estado','Sucesso','Latência','Falhas','Detalhes'].map(x=><th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{data.providers.map(p=>{const h=p.health||{};const status=stateFor(p);return <tr key={p.id} className="border-t border-white/[.07]"><td className="px-4 py-3"><strong>{p.name}</strong><small className="block text-muted">{p.model}</small></td><td className="px-4 py-3"><Status value={status[1]}>{status[0]}</Status></td><td className="px-4 py-3">{h.success_rate==null?'—':`${h.success_rate.toFixed(1)}%`}<small className="block text-muted">{h.samples||0} chamadas</small></td><td className="px-4 py-3">{h.avg_latency_ms==null?'—':`${h.avg_latency_ms} ms`}</td><td className="px-4 py-3">{h.consecutive_failures||0}</td><td className="px-4 py-3"><Button small onClick={async()=>{setProvider(p);try{setEntries(await api(`/providers/${p.id}/attempts`))}catch(e){setEntries([])}}}>Histórico</Button></td></tr>})}</tbody></table></div>:<Empty title="Cadastre um provedor">As medições reais aparecerão aqui.</Empty>}<p className="px-5 py-4 text-[11px] text-muted">Taxa e tempo médio usam as últimas chamadas reais desde esta atualização.</p>{provider&&<Modal title={`Saúde: ${provider.name}`} description="Últimas 30 chamadas reais, sem expor credenciais." onClose={()=>{setProvider(null);setEntries(null)}} onSubmit={e=>{e.preventDefault();setProvider(null)}} submit="Fechar"><div className="max-h-72 overflow-auto">{entries===null?<p className="text-sm text-muted">Carregando…</p>:entries.length?entries.map((entry,i)=><div key={i} className="flex items-center justify-between gap-3 border-b border-white/10 py-3 text-xs"><span>{dateLabel(entry.created_at,true)}<small className="block text-muted">{entry.http_status?`HTTP ${entry.http_status}`:entry.category||'—'}</small></span><Status value={entry.success?'completed':'failed'}>{entry.success?'Sucesso':'Falhou'}</Status><span>{entry.latency_ms} ms</span></div>):<p className="text-sm text-muted">Nenhum teste ou execução registrada.</p>}</div></Modal>}</section>
}

function Providers({ data, onEdit, onDelete, onTest, onHistory, onConnected }) {
  const [search,setSearch]=useState('');const [filter,setFilter]=useState('free')
  const filteredProviders=data.providers.filter(p=>(filter==='all'||providerCategory(p)===filter)&&`${p.name} ${p.model} ${p.kind}`.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')))
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4">
    <Heading eyebrow="INTEGRAÇÕES" title="Conecte sua equipe de IA" description="Catálogo oficial de modelos, configuração automática e conexões verificadas." action={<Button quiet onClick={()=>onEdit(null)}>Configuração manual</Button>} />
    <ProviderCatalog filter={filter} onFilter={setFilter} presets={providerPresets.map(p=>({...p,access:p.group,quick:false,keys_url:providerKeyLinks[p.kind]||providerKeyLinks.compatible,source_url:providerKeyLinks[p.kind]||providerKeyLinks.compatible,checked_at:"catálogo manual"}))} api={api} providers={data.providers} onConnected={onConnected} onManual={kind=>onEdit(null,providerPresets.find(p=>p.kind===kind))}/>
    <div className="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 className="text-sm font-semibold">Suas conexões · {filteredProviders.filter(p=>p.enabled).length} ativas</h2><input aria-label="Buscar conexão salva" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar conexão ou modelo..." className="min-h-10 rounded-xl border border-white/10 bg-panel px-3 text-xs"/></div>
    <div className="overflow-x-auto rounded-2xl border border-white/[.09] bg-panel"><table className="w-full min-w-[850px] text-left text-xs"><thead className="bg-white/[.035] text-[10px] uppercase tracking-wider text-muted"><tr>{['Provedor','Modelo','Prioridade','Saúde','Ações'].map(x=><th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{filteredProviders.map(p=>{const h=p.health||{};const state=!p.enabled?['Pausado','failed']:h.state==='healthy'?['Saudável','completed']:h.state==='suspended'?['Suspenso','failed']:h.state==='degraded'?['Instável','running']:['Sem medições',''];return <tr key={p.id} className="border-t border-white/[.07]"><td className="px-4 py-4"><strong>{p.name}</strong><small className="block text-muted">{providerKindLabels[p.kind]||p.kind} · {p.has_key?'Chave armazenada':'Sem chave'}</small></td><td className="px-4 py-4">{p.model}</td><td className="px-4 py-4">{p.priority}</td><td className="px-4 py-4"><Status value={state[1]}>{state[0]}</Status><small className="mt-1 block text-muted">{h.success_rate==null?'—':`${h.success_rate.toFixed(1)}% sucesso`} · {h.avg_latency_ms==null?'—':`${h.avg_latency_ms} ms`}</small></td><td className="px-4 py-4"><div className="flex justify-end gap-1"><Button small onClick={()=>onTest(p)}>Testar</Button><Button small quiet onClick={()=>onHistory(p)}>Histórico</Button><Button small quiet onClick={()=>onEdit(p)}>Editar</Button><Button small danger onClick={()=>onDelete(p)}>Excluir</Button></div></td></tr>})}{!filteredProviders.length&&<tr><td colSpan="5"><Empty icon="⬡" title={data.providers.length?'Nenhuma conexão neste filtro':'Nenhum provedor conectado'}>{data.providers.length?'Ajuste a categoria ou o texto pesquisado.':'Escolha um preset acima para preencher a conexão.'}</Empty></td></tr>}</tbody></table></div>
  </div>
}

function Agents({ data, onEdit }) {
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow="EQUIPE IA" title="Seus trabalhadores inteligentes" description="Veja a especialidade de cada agente nos cartões ou altere-a em Configurar." action={<Button primary onClick={()=>onEdit(null)}>＋ Criar trabalhador</Button>} /><section className="mb-5 rounded-2xl border border-white/[.09] bg-panel p-4"><p className="mb-3 text-[10px] font-bold uppercase tracking-wider text-muted">Especialidades disponíveis</p><div className="flex flex-wrap gap-2">{specialtyOptions.map(([,label,description])=><span key={label} title={description} className="rounded-xl border border-lilac/15 bg-lilac/[.05] px-3 py-2 text-[11px] text-copy">{label}</span>)}</div><p className="mt-3 text-[10px] text-muted">Cada cartão abaixo mostra a especialidade atribuída. Use “Configurar” para trocar.</p></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{data.agents.map(agent=><article key={agent.id} className="rounded-2xl border border-white/[.09] bg-panel p-5 transition hover:-translate-y-0.5 hover:border-lilac/30"><div className="flex items-center justify-between"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-gradient-to-br from-[#43455a] to-[#303047] text-2xl text-lilac">{agent.avatar}</span><Status value={agent.enabled?'completed':'failed'}>{agent.enabled?'Disponível':'Desativado'}</Status></div><h2 className="mt-4 text-base font-semibold">{agent.name}</h2><p className="mt-2 min-h-12 text-xs leading-5 text-muted">{agent.instructions.slice(0,116)}{agent.instructions.length>116?'…':''}</p><div className="mt-3 flex flex-wrap gap-2"><span className="rounded-lg border border-lilac/20 bg-lilac/[.06] px-2 py-1 text-[10px] text-lilac"><span className="mr-1 text-muted">ESPECIALIDADE</span>{specialtyOptions.find(([value])=>value===agent.specialty)?.[1]||agent.specialty}</span><span className="rounded-lg border border-white/10 px-2 py-1 text-[10px] text-muted">{data.providers.find(p=>p.id===agent.provider_id)?.name||'Modelo automático'}</span></div><div className="mt-4 flex items-center justify-between border-t border-white/[.08] pt-4"><small className="text-[10px] text-muted">{agent.max_concurrency} tarefa(s)/agente</small><Button small onClick={()=>onEdit(agent)}>Configurar →</Button></div></article>)}</div>{!data.agents.length&&<Empty title="Nenhum trabalhador configurado">Crie um trabalhador para organizar sua equipe.</Empty>}</div>
}

function Projects({ data, onCreate, onChat, onMemory }) {
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow="ORGANIZAÇÃO" title="Projetos" description="Agrupe conversas por iniciativa e mantenha o histórico acessível." action={<Button primary onClick={onCreate}>＋ Criar projeto</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{data.projects.map(project=><article key={project.id} className="rounded-2xl border border-white/[.09] bg-panel p-5"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-lilac/10 text-xl text-lilac">▤</span><h2 className="mt-4 font-semibold">{project.name}</h2><p className="mt-2 min-h-10 text-xs leading-5 text-muted">{project.description||'Sem descrição.'}</p><div className="mt-4 flex items-center justify-between border-t border-white/[.08] pt-4"><small className="text-[10px] text-muted">{dateLabel(project.created_at)}</small><div className="flex flex-wrap gap-2"><Button small quiet onClick={()=>onMemory(project.id)}>⌕ Memória</Button><Button small onClick={()=>onChat(project.id)}>Nova conversa →</Button></div></div></article>)}</div>{!data.projects.length&&<Empty icon="▤" title="Nenhum projeto criado">Comece criando um espaço para suas tarefas.</Empty>}</div>
}

function Workflows({ data, onEdit, onUse }) {
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow="AUTOMAÇÃO" title="Fluxos de trabalho" description="Monte etapas de agentes e aprovações, em sequência ou em paralelo." action={<Button primary onClick={()=>onEdit(null)}>＋ Criar fluxo</Button>} /><div className="mb-5 rounded-2xl border border-white/10 bg-panel p-4 text-xs leading-5 text-muted">O motor oferece dependências, paralelismo, aprovações e checkpoints. Ferramentas externas e ações irreversíveis não são executadas nesta versão.</div><section className="overflow-hidden rounded-2xl border border-white/[.09] bg-panel"><div className="flex items-center justify-between px-5 py-4"><h2 className="text-sm font-semibold">Fluxos disponíveis</h2><small className="text-muted">{data.workflows.length} salvo(s)</small></div>{data.workflows.map(flow=><div key={flow.id} className="flex flex-wrap items-center justify-between gap-3 border-t border-white/[.07] px-5 py-4"><div><strong className="text-sm">⌁ {flow.name}</strong><p className="mt-1 text-xs text-muted">{flow.description||'Sem descrição'} · {flow.definition.nodes.length} blocos · v{flow.version}</p></div><div className="flex gap-2"><Button small onClick={()=>onEdit(flow)}>Editar</Button><Button small primary onClick={()=>onUse(flow.id)}>Usar no chat →</Button></div></div>)}{!data.workflows.length&&<Empty icon="⌁" title="Crie seu primeiro fluxo">Conecte trabalhadores e adicione etapas de aprovação.</Empty>}</section></div>
}

function History({ data, onOpen, onResume, onRefresh }) {
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow="REGISTROS" title="Histórico de execuções" description="Consulte resultados, erros e horários das tarefas persistidas." action={<Button onClick={onRefresh}>↻ Atualizar</Button>} /><div className="overflow-x-auto rounded-2xl border border-white/[.09] bg-panel"><table className="w-full min-w-[740px] text-left text-xs"><thead className="bg-white/[.035] text-[10px] uppercase tracking-wider text-muted"><tr>{['Tarefa','Data','Status','Custo estimado*','Ações'].map(x=><th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{data.runs.map(run=><tr key={run.id} className="border-t border-white/[.07]"><td className="max-w-sm px-4 py-4"><strong className="block truncate">{run.prompt.slice(0,85)}</strong><small className="text-muted">ID {run.id.slice(0,8)}</small></td><td className="px-4 py-4">{dateLabel(run.created_at,true)}</td><td className="px-4 py-4"><Status value={run.status}/></td><td className="px-4 py-4">US$ {Number(run.total_cost).toFixed(5)}</td><td className="px-4 py-4"><div className="flex justify-end gap-2">{['failed','cancelled'].includes(run.status)&&<Button small primary onClick={()=>onResume(run.id)}>↻ Retomar</Button>}<Button small onClick={()=>onOpen(run)}>Abrir chat →</Button></div></td></tr>)}</tbody></table>{!data.runs.length&&<Empty icon="◷" title="Nenhuma tarefa registrada">As execuções concluídas aparecem aqui.</Empty>}</div><p className="mt-3 text-[11px] text-muted">* Estimativas locais quando um preço por token é informado.</p></div>
}

function Settings({ theme, onTheme, me, onLogout }) {
  return <div className="mx-auto w-full max-w-[1440px] px-8 py-8 max-sm:px-4"><Heading eyebrow="PREFERÊNCIAS" title="Configurações" description="Personalize a aparência e gerencie sua sessão." /><div className="grid gap-4 lg:grid-cols-2"><Panel title="Aparência"><div className="px-5 pb-5"><p className="mb-4 text-sm text-muted">Alterne entre os temas da interface.</p><Button onClick={onTheme}>◐ Mudar para tema {theme==='dark'?'claro':'escuro'}</Button></div></Panel><Panel title="Sua conta"><div className="px-5 pb-5"><p className="text-sm">{me.email}</p><p className="my-3 text-xs leading-5 text-muted">Os dados ficam nesta instalação. Faça backup de data/, incluindo a chave de criptografia.</p><Button danger onClick={onLogout}>Sair da conta</Button></div></Panel></div></div>
}

function EditorDialog({ modal, data, onClose, onSave }) {
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [nodes,setNodes]=useState(modal.item?.definition?.nodes||[]);const editing=modal.item
  const [presetId,setPresetId]=useState(modal.preset?.id||'')
  const [providerKind,setProviderKind]=useState(editing?.kind||modal.preset?.kind||'openai')
  const [providerName,setProviderName]=useState(editing?.name||modal.preset?.name||'')
  const [providerModel,setProviderModel]=useState(editing?.model||modal.preset?.model||'')
  const [providerBaseUrl,setProviderBaseUrl]=useState(editing?.base_url||modal.preset?.base_url||'')
  const [agentSpecialty,setAgentSpecialty]=useState(editing?.specialty||'custom')
  const chooseProviderPreset=id=>{setPresetId(id);const p=providerPresets.find(item=>item.id===id);if(!p)return;setProviderKind(p.kind);setProviderName(p.name.trim());setProviderModel(p.model);setProviderBaseUrl(p.base_url||'')}
  async function submit(e) {
    e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget)
    try {
      let payload
      if(modal.kind==='provider')payload={name:f.get('name'),kind:f.get('kind'),model:f.get('model'),api_key:f.get('api_key'),base_url:f.get('base_url'),priority:+f.get('priority'),enabled:f.get('enabled')==='on',input_price:f.get('input_price')===''?null:+f.get('input_price'),output_price:f.get('output_price')===''?null:+f.get('output_price')}
      if(modal.kind==='agent')payload={name:f.get('name'),specialty:f.get('specialty'),instructions:f.get('instructions'),avatar:f.get('avatar')||'✦',provider_id:f.get('provider_id')||null,model:f.get('model')||null,enabled:f.get('enabled')==='on'}
      if(modal.kind==='project')payload={name:f.get('name'),description:f.get('description')}
      if(modal.kind==='workflow'){if(!nodes.length)throw new Error('Adicione pelo menos uma etapa ao fluxo.');payload={name:f.get('name'),description:f.get('description'),definition:{nodes}}}
      await onSave(modal.kind,editing?.id,payload);onClose()
    } catch(ex){setError(ex.message)} finally{setBusy(false)}
  }
  const agentOptions=data.agents.filter(a=>a.enabled)
  const addNode=parallel=>{const type=document.querySelector('[name="node-kind"]')?.value||'agent',agentId=document.querySelector('[name="node-agent"]')?.value,agent=agentOptions.find(a=>a.id===agentId);if(type==='agent'&&!agent){setError('Selecione um trabalhador.');return}const last=nodes.at(-1);setNodes(old=>[...old,{id:crypto.randomUUID(),kind:type,agent_id:type==='agent'?agentId:null,name:type==='agent'?agent.name:'Aprovação humana',deps:last?(parallel?last.deps:[last.id]):[],instructions:''}]);setError('')}
  return <Modal title={modal.kind==='provider'?(editing?'Editar provedor':'Conectar provedor'):modal.kind==='agent'?(editing?'Configurar trabalhador':'Novo trabalhador'):modal.kind==='project'?'Novo projeto':editing?'Editar fluxo':'Criar fluxo'} description={modal.kind==='provider'?'Configure um provedor de IA ao qual você possui acesso.':modal.kind==='agent'?'Defina a identidade e as instruções do trabalhador.':modal.kind==='project'?'Organize suas conversas em um workspace.':'Monte etapas sequenciais ou paralelas, com aprovação opcional.'} onClose={onClose} onSubmit={submit} busy={busy} error={error} submit={modal.kind==='workflow'?'Salvar fluxo':modal.kind==='provider'?'Conectar API':modal.kind==='agent'?'Salvar trabalhador':modal.kind==='project'?'Criar projeto':'Salvar alterações'}>
    {modal.kind==='provider'&&<><label className="mb-4 block text-xs font-medium text-muted">Preset de conexão<select value={presetId} onChange={e=>chooseProviderPreset(e.target.value)} className="mt-2 min-h-11 w-full rounded-xl border border-white/10 bg-[#1b1b1b] px-3 text-sm text-copy"><option value="">Escolha um provedor ou mantenha personalizado</option>{['Local','Grátis limitado','Cotas/créditos','Verificar plano','Uso pago','Créditos de avaliação','Créditos / uso pago','Grátis/uso pago','Local / próprio','Personalizado'].map(group=><optgroup key={group} label={group}>{providerPresets.filter(p=>p.group===group).map(p=><option key={p.id} value={p.id}>{p.name.trim()} — {p.badge}</option>)}</optgroup>)}</select>{presetId&&<small className="mt-2 block leading-4 text-muted">{providerPresets.find(p=>p.id===presetId)?.note}</small>}</label><div className="grid gap-2 sm:grid-cols-2"><Field label="Nome" name="name" value={providerName} onChange={e=>setProviderName(e.target.value)} required placeholder="Meu provedor"/><label className="mb-4 block text-xs font-medium text-muted">Protocolo<select name="kind" value={providerKind} onChange={e=>setProviderKind(e.target.value)} className="mt-2 min-h-11 w-full rounded-xl border border-white/10 bg-[#1b1b1b] px-3 text-sm text-copy">{Object.entries(providerKindLabels).map(([kind,label])=><option key={kind} value={kind}>{label}</option>)}</select></label></div><Field label="Identificador real do modelo" name="model" value={providerModel} onChange={e=>setProviderModel(e.target.value)} required placeholder="Consulte o catálogo do provedor"/><div className="grid items-end gap-2 sm:grid-cols-[1fr_auto]"><Field label={editing?'Nova chave (em branco mantém a atual)':'Chave de API (se exigida pelo provedor)'} name="api_key" type="password" autoComplete="new-password"/><a href={providerKeyLinks[providerKind]||providerKeyLinks.compatible} target="_blank" rel="noopener noreferrer" className="mb-4 inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-lilac/25 bg-lilac/[.08] px-4 text-[10px] font-bold tracking-wider text-lilac transition hover:border-lilac/50 hover:bg-lilac/[.15]">CHAVE API ↗</a></div>{['ollama','lmstudio','jan','localai','vllm','llamacpp'].includes(providerKind)&&<p className="-mt-2 mb-4 text-[10px] leading-4 text-muted">Este provedor local normalmente não precisa de chave; o botão abre a documentação para ativar a API local.</p>}{providerKind==='compatible'&&<p className="-mt-2 mb-4 text-[10px] leading-4 text-muted">Para endpoints personalizados, gere a chave no painel do serviço que fornece a API.</p>}<Field label="URL base (opcional)" name="base_url" type="url" value={providerBaseUrl} onChange={e=>setProviderBaseUrl(e.target.value)} placeholder="Usar endereço padrão do preset"/><div className="grid gap-2 sm:grid-cols-2"><Field label="Prioridade (1 = primeira)" name="priority" type="number" min="1" value={editing?.priority||5}/><Field label="US$ / milhão de tokens de entrada" name="input_price" type="number" step="0.000001" min="0" value={editing?.input_price??''}/></div><Field label="US$ / milhão de tokens de saída" name="output_price" type="number" step="0.000001" min="0" value={editing?.output_price??''}/><label className="flex items-center gap-2 text-xs text-muted"><input name="enabled" type="checkbox" defaultChecked={editing?.enabled!==false} className="accent-violet-400"/>Provedor habilitado</label></>}
    {modal.kind==='agent'&&<><div className="grid gap-2 sm:grid-cols-2"><Field label="Nome do trabalhador" name="name" value={editing?.name||''} required/><Field label="Avatar (caractere)" name="avatar" value={editing?.avatar||'✦'}/></div><label className="mb-4 block text-xs font-medium text-muted">Especialização do agente<select name="specialty" value={agentSpecialty} onChange={e=>setAgentSpecialty(e.target.value)} className="mt-2 min-h-11 w-full rounded-xl border border-white/10 bg-[#1b1b1b] px-3 text-sm text-copy">{specialtyOptions.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><small className="mt-2 block leading-4 text-muted">{specialtyOptions.find(([value])=>value===agentSpecialty)?.[2]} O motor usa essa categoria para encaminhar tarefas automaticamente.</small></label><label className="mb-4 block text-xs font-medium text-muted">Instruções de sistema<textarea name="instructions" defaultValue={editing?.instructions||'Você é um assistente especialista. Entregue resultados concretos e verificáveis.'} required minLength="4" rows="5" className="mt-2 w-full rounded-xl border border-white/10 bg-[#1b1b1b] p-3 text-sm text-copy outline-none focus:border-lilac/50"/></label><div className="grid gap-2 sm:grid-cols-2"><label className="mb-4 block text-xs font-medium text-muted">Provedor preferencial<select name="provider_id" defaultValue={editing?.provider_id||''} className="mt-2 min-h-11 w-full rounded-xl border border-white/10 bg-[#1b1b1b] px-3 text-sm text-copy"><option value="">Automático — qualquer provedor ativo</option>{data.providers.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><Field label="Modelo específico (opcional)" name="model" value={editing?.model||''}/></div><label className="flex items-center gap-2 text-xs text-muted"><input name="enabled" type="checkbox" defaultChecked={editing?.enabled!==false} className="accent-violet-400"/>Ativo</label></>}
    {modal.kind==='project'&&<><Field label="Nome do projeto" name="name" required/><label className="mb-4 block text-xs font-medium text-muted">Descrição<textarea name="description" rows="3" className="mt-2 w-full rounded-xl border border-white/10 bg-[#1b1b1b] p-3 text-sm text-copy outline-none focus:border-lilac/50"/></label></>}
    {modal.kind==='workflow'&&<><Field label="Nome do fluxo" name="name" value={editing?.name||'Fluxo multiagente'} required/><Field label="Descrição" name="description" value={editing?.description||''}/><div className="mb-4 rounded-2xl border border-white/10 bg-[#151518] p-4"><p className="mb-3 text-xs font-semibold">Adicionar etapa</p><div className="grid gap-2 sm:grid-cols-2"><select name="node-kind" className="rounded-xl border border-white/10 bg-card p-2 text-xs"><option value="agent">Trabalhador IA</option><option value="approval">Aprovação humana</option></select><select name="node-agent" className="rounded-xl border border-white/10 bg-card p-2 text-xs">{agentOptions.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></div><div className="mt-3 flex gap-2"><Button small type="button" onClick={()=>addNode(false)}>＋ Sequencial</Button><Button small type="button" onClick={()=>addNode(true)}>＋ Paralelo</Button></div></div><p className="mb-2 text-xs font-medium text-muted">Etapas do fluxo</p>{nodes.length?nodes.map((node,i)=><div key={node.id} className="mb-2 flex items-center justify-between rounded-xl border border-white/10 bg-card p-3 text-xs"><span>{i+1}. {node.name}</span><button type="button" onClick={()=>setNodes(old=>old.filter(n=>n.id!==node.id).map(n=>({...n,deps:n.deps.filter(id=>id!==node.id)})))} className="text-muted hover:text-rose-300">Remover</button></div>):<p className="text-xs text-muted">Adicione uma etapa para começar.</p>}</>}
  </Modal>
}

export default function App() {
  const [user,setUser]=useState(null);const [authReady,setAuthReady]=useState(false);const [page,setPage]=useState('chat');const [menuOpen,setMenuOpen]=useState(false);const [theme,setTheme]=useState(localStorage.getItem('central-theme')||'dark');const [data,setData]=useState(emptyData);const [stats,setStats]=useState(null);const [modal,setModal]=useState(null);const [toast,setToast]=useState('');const [currentConvo,setCurrentConvo]=useState(null);const [selectedProject,setSelectedProject]=useState(null);const [memoryOpen,setMemoryOpen]=useState(false);const [memoryTargetProject,setMemoryTargetProject]=useState(null);const [selectedWorkflow,setSelectedWorkflow]=useState(null);const [messages,setMessages]=useState([]);const [steps,setSteps]=useState([]);const [mode,setMode]=useState('auto');const [selectedAgent,setSelectedAgent]=useState('');const [prompt,setPrompt]=useState('');const [files,setFiles]=useState([]);const [currentRun,setCurrentRun]=useState(null);const sourceRef=useRef(null);const toastTimer=useRef(null)
  const notify=useCallback(message=>{setToast(message);clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),5000)},[])
  const loadAll=useCallback(async()=>{const keys=['agents','providers','projects','conversations','workflows','runs'];const results=await Promise.allSettled(keys.map(key=>api(`/${key}`)));setData(old=>Object.fromEntries(keys.map((key,i)=>[key,results[i].status==='fulfilled'?results[i].value:old[key]])))},[])
  const refreshStats=useCallback(async()=>{try{setStats(await api('/dashboard'))}catch(error){notify(error.message)}},[notify])
  useEffect(()=>{document.documentElement.classList.toggle('light',theme==='light');localStorage.setItem('central-theme',theme)},[theme])
  useEffect(()=>{let cancelled=false;api('/me').then(async me=>{if(cancelled)return;setUser(me);await loadAll()}).catch(()=>{}).finally(()=>{if(!cancelled)setAuthReady(true)});return()=>{cancelled=true}},[loadAll])
  useEffect(()=>{if(user&&(page==='dashboard'||page==='monitoring'))refreshStats()},[page,user,refreshStats])
  useEffect(()=>{if(!user||page!=='chat')return;let active=true;if(!currentConvo){setMessages([]);return}api(`/conversations/${currentConvo}/messages`).then(items=>{if(active)setMessages(items.map(m=>({role:m.role,agent:m.agent_name||'Central IA',content:m.content})))}).catch(error=>notify(error.message));return()=>{active=false}},[currentConvo,page,user,notify])
  useEffect(()=>()=>{sourceRef.current?.close();clearTimeout(toastTimer.current)},[])
  async function login(authMode,credentials){const me=await api(`/${authMode}`,'POST',credentials);setUser(me);setPage('chat');await loadAll()}
  async function logout(){sourceRef.current?.close();await api('/logout','POST');setMenuOpen(false);setUser(null);setCurrentConvo(null);setData(emptyData);setMessages([])}
  const navigate=next=>{sourceRef.current?.close();setPage(next);setMenuOpen(false)}
  function newChat(){sourceRef.current?.close();setCurrentRun(null);setCurrentConvo(null);setSelectedProject(null);setSteps([]);setMessages([]);setFiles([]);setPrompt('');setPage('chat');setMenuOpen(false)}
  async function openConversation(id){sourceRef.current?.close();setCurrentRun(null);setSteps([]);setCurrentConvo(id);setSelectedProject(null);setPage('chat');setMenuOpen(false)}
  async function moveConversationToProject(cid, projectId) {
    await api('/conversations/' + encodeURIComponent(cid) + '/project', 'PATCH', {project_id:projectId})
    await loadAll()
    notify(projectId ? 'Conversa vinculada ao projeto. A memória passou a usar este contexto.' : 'Conversa desvinculada. Agora só utiliza memória curta.')
  }
  function openMemoryPanel(projectId = null) {setMemoryTargetProject(projectId);setMemoryOpen(true)}
  async function sendMessage(){const text=prompt.trim();if(!text||currentRun)return;const attached=files.map(f=>`\n\nArquivo: ${f.name}\n\`\`\`\n${f.content}\n\`\`\``).join('');setPrompt('');setFiles([]);setMessages(old=>[...old,{role:'user',content:text+attached}]);try{let cid=currentConvo;if(!cid){const convo=await api('/conversations','POST',{title:'Nova conversa',project_id:selectedProject||null});cid=convo.id;setCurrentConvo(cid);setSelectedProject(null);setData(old=>({...old,conversations:[convo,...old.conversations]}))}const run=await api('/runs','POST',{conversation_id:cid,prompt:text+attached,mode,agent_ids:selectedAgent?[selectedAgent]:[],workflow_id:selectedWorkflow||null},{'Idempotency-Key':crypto.randomUUID()});setSelectedWorkflow(null);setCurrentRun(run.id);setSteps([]);const stream=new EventSource(`/api/runs/${run.id}/events?after=0`);sourceRef.current=stream;stream.onmessage=event=>{let msg;try{msg=JSON.parse(event.data)}catch{return}const d=msg.data||{};if(msg.event==='token')setMessages(old=>{const index=old.findIndex(item=>item.stepId===d.step_id);if(index<0)return [...old,{role:'assistant',agent:d.agent,content:d.text,stepId:d.step_id}];return old.map((item,i)=>i===index?{...item,content:item.content+d.text}:item)});if(msg.event==='step_reset')setMessages(old=>old.map(item=>item.stepId===d.step_id?{...item,content:''}:item));if(msg.event==='run_created')setSteps(d.plan.map(item=>({...item,status:'queued'})));if(msg.event==='step_status')setSteps(old=>old.map(item=>item.id===d.id?{...item,...d}:item));if(msg.event==='model_selected')setSteps(old=>old.map(item=>item.id===d.step_id?{...item,model:d.model,provider:d.provider}:item));if(msg.event==='approval_requested')setSteps(old=>old.map(item=>item.id===d.step_id?{...item,status:'awaiting_approval'}:item));if(['provider_error','failover','provider_suspended','provider_recovered','provider_probe'].includes(msg.event))setMessages(old=>[...old,{type:'event',content:d.message||`${d.provider||'Provedor'}: ${d.category||msg.event}`}]);if(msg.event==='run_failed'){notify(`Falha na execução: ${d.error}`);finishRun(stream,cid,false)}if(msg.event==='run_completed')finishRun(stream,cid,true);if(msg.event==='run_status'&&d.status==='cancelled'){notify('Execução cancelada.');finishRun(stream,cid,false)}};stream.onerror=()=>{if(sourceRef.current===stream&&stream.readyState===EventSource.CLOSED)notify('A conexão foi interrompida. Atualize o histórico da conversa.')}}catch(error){notify(error.message);setCurrentRun(null)}}
  async function finishRun(stream,cid,success){stream.close();if(sourceRef.current===stream)sourceRef.current=null;setCurrentRun(null);if(success){try{const saved=await api(`/conversations/${cid}/messages`);setMessages(saved.map(m=>({role:m.role,agent:m.agent_name||'Central IA',content:m.content})))}catch{}}await loadAll()}
  async function cancelRun(){if(!currentRun)return;try{await api(`/runs/${currentRun}/cancel`,'POST')}catch(error){notify(error.message)}}
  async function approval(stepId,approved){if(!currentRun)return;try{await api(`/runs/${currentRun}/steps/${stepId}/approval`,'POST',{approved});notify(approved?'Etapa aprovada.':'Etapa rejeitada.')}catch(error){notify(error.message)}}
  async function saveEditor(kind,id,payload){const endpoints={provider:'/providers',agent:'/agents',project:'/projects',workflow:'/workflows'};if(id&&kind!=='project')await api(`${endpoints[kind]}/${id}`,'PUT',payload);else await api(endpoints[kind],'POST',payload);await loadAll();if(kind==='provider'||kind==='agent')notify(kind==='provider'?'Provedor salvo com segurança.':'Trabalhador salvo.')}
  async function removeProvider(provider){if(!window.confirm(`Excluir o provedor ${provider.name}? As credenciais serão apagadas.`))return;try{await api(`/providers/${provider.id}`,'DELETE');await loadAll();notify('Provedor excluído.')}catch(error){notify(error.message)}}
  async function testProvider(provider){try{const result=await api(`/providers/${provider.id}/test`,'POST');notify(result.ok?`Conexão validada: ${result.response}`:`Falha: ${result.error}`);await loadAll()}catch(error){notify(error.message)}}
  async function openRun(run){await openConversation(run.conversation_id);try{const detail=await api(`/runs/${run.id}`);if(['running','queued','awaiting_approval'].includes(detail.status)){setCurrentRun(run.id);setSteps(detail.steps||[]);const stream=new EventSource(`/api/runs/${run.id}/events?after=0`);sourceRef.current=stream;stream.onmessage=event=>{const msg=JSON.parse(event.data),d=msg.data||{};if(msg.event==='token')setMessages(old=>{const idx=old.findIndex(item=>item.stepId===d.step_id);return idx<0?[...old,{role:'assistant',agent:d.agent,content:d.text,stepId:d.step_id}]:old.map((item,i)=>i===idx?{...item,content:item.content+d.text}:item)});if(msg.event==='step_status')setSteps(old=>old.map(item=>item.id===d.id?{...item,...d}:item));if(msg.event==='run_completed'||msg.event==='run_failed')finishRun(stream,run.conversation_id,msg.event==='run_completed')}}}catch(error){notify(error.message)}}
  async function resumeRun(id){try{await api(`/runs/${id}/resume`,'POST');await loadAll();await refreshStats();notify('Execução retomada a partir dos checkpoints concluídos.')}catch(error){notify(error.message)}}
  function useWorkflow(id){setCurrentConvo(null);setMessages([]);setSelectedWorkflow(id);setSelectedAgent('');setMode('team');setPage('chat');notify('Fluxo selecionado. Envie a tarefa para executá-lo.')}
  function runCommand(command) {
    setPrompt('')
    if (command === '/novo') return newChat()
    if (command === '/menu') return setMenuOpen(true)
    if (command === '/ajuda') {
      setMessages(old => [...old, { role: 'assistant', agent: 'Comandos da Central', content: 'Use /novo para iniciar uma conversa, /menu para abrir a navegação, /agentes, /provedores, /projetos, /fluxos, /historico, /monitoramento ou /configuracoes para abrir cada área. Durante uma etapa pausada, /aprovar autoriza e /rejeitar nega a continuação.' }])
      return
    }
    if (command === '/aprovar' || command === '/rejeitar') {
      const pending = steps.find(step => step.status === 'awaiting_approval')
      if (!pending) return notify('Não há etapa aguardando aprovação nesta conversa.')
      return approval(pending.id, command === '/aprovar')
    }
    const destinations = { '/agentes': 'agents', '/provedores': 'providers', '/projetos': 'projects', '/fluxos': 'workflows', '/historico': 'history', '/monitoramento': 'monitoring', '/configuracoes': 'settings' }
    if (destinations[command]) return navigate(destinations[command])
  }
  const selectSuggestion=value=>setPrompt(value)
  if(!authReady)return <div className="grid min-h-screen place-items-center bg-ink text-sm text-muted">Abrindo sua central…</div>
  if(!user)return <><Auth onLogin={login} notify={notify}/>{toast&&<div role="status" className="fixed bottom-5 right-5 z-[60] max-w-sm rounded-2xl border border-white/15 bg-[#28292c] px-4 py-3 text-sm shadow-xl">{toast}</div>}</>
  return <div className="relative flex h-screen min-h-[560px] overflow-hidden bg-ink text-copy">
    {menuOpen && <><button aria-label="Fechar menu" onClick={() => setMenuOpen(false)} className="fixed inset-0 z-40 cursor-default bg-black/60 backdrop-blur-[2px]"/><div className="menu-drawer fixed inset-y-0 left-0 z-50 w-[286px] max-w-[88vw] shadow-2xl shadow-black/50"><Sidebar page={page} data={{...data,currentConvo}} me={user} onNavigate={navigate} onNewChat={newChat} onSwitch={openConversation} onLogout={() => logout().catch(e => notify(e.message))}/></div></>}
    <main className="relative flex min-h-0 min-w-0 flex-1 flex-col bg-[radial-gradient(ellipse_at_55%_42%,#1c3762,transparent_49%),#131314]">
      <header className="z-10 flex h-[58px] shrink-0 items-center justify-between border-b border-white/[.06] bg-[#131314d9] px-5 backdrop-blur-xl max-sm:px-3">
        <div className="flex min-w-0 items-center gap-3"><button type="button" aria-label="Abrir menu" title="Menu" onClick={() => setMenuOpen(true)} className="menu-toggle grid h-9 w-9 shrink-0 place-items-center rounded-xl border border-white/10 text-lg text-muted transition hover:bg-white/[.07] hover:text-copy"><span aria-hidden="true">☰</span></button><div className="min-w-0"><p className="truncate text-xs text-muted">{page === 'chat' ? 'Central IA' : 'Workspace'}</p><strong className="block truncate text-[13px] font-medium text-copy">{pageNames[page]}</strong></div></div>
        <div className="flex items-center gap-3"><span className="flex items-center gap-2 rounded-full border border-emerald-300/15 bg-emerald-300/[.06] px-2.5 py-1.5 text-[10px] text-emerald-200 max-sm:hidden"><span className="h-1.5 w-1.5 rounded-full bg-emerald-300"/>Sistema online</span><button title="Alternar tema" onClick={() => setTheme(old => old === 'dark' ? 'light' : 'dark')} className="rounded-lg p-2 text-muted hover:bg-white/[.06]">◐</button></div>
      </header>
      <section className={'min-h-0 flex-1 ' + (page === 'chat' ? 'overflow-hidden' : 'scrollbar-soft overflow-y-auto')}>
        {page === 'chat' && <ChatPage data={data} messages={messages} steps={steps} mode={mode} setMode={setMode} selectedAgent={selectedAgent} setSelectedAgent={setSelectedAgent} prompt={prompt} setPrompt={setPrompt} files={files} setFiles={setFiles} running={!!currentRun} onSend={sendMessage} onCancel={cancelRun} onApproval={approval} onSuggest={selectSuggestion} currentConvo={currentConvo} onMenu={() => setMenuOpen(true)} onCommand={runCommand} selectedProject={selectedProject} onOpenMemory={() => openMemoryPanel()}/>}
        {(page === 'dashboard' || page === 'monitoring') && <Dashboard data={data} stats={stats} page={page} navigate={navigate} onHistory={provider => setModal({kind:'health',item:provider})}/>}
        {page === 'providers' && <Providers onConnected={loadAll} data={data} onEdit={(item,preset) => setModal({kind:'provider',item,preset})} onDelete={removeProvider} onTest={testProvider} onHistory={provider => setModal({kind:'health',item:provider})}/>}
        {page === 'agents' && <Agents data={data} onEdit={item => setModal({kind:'agent',item})}/>}
        {page === 'projects' && <Projects data={data} onCreate={() => setModal({kind:'project'})} onChat={id => {setCurrentConvo(null);setSelectedProject(id);setPage('chat')}} onMemory={id => openMemoryPanel(id)}/>}
        {page === 'workflows' && <Workflows data={data} onEdit={item => setModal({kind:'workflow',item})} onUse={useWorkflow}/>}
        {page === 'history' && <History data={data} onOpen={openRun} onResume={resumeRun} onRefresh={() => loadAll().then(refreshStats)}/>}
        {page === 'settings' && <Settings theme={theme} onTheme={() => setTheme(old => old === 'dark' ? 'light' : 'dark')} me={user} onLogout={() => logout().catch(e => notify(e.message))}/>}
      </section>
    </main>
    {memoryOpen && <ConversationMemoryPanel
      key={(memoryTargetProject || currentConvo || selectedProject || 'avulsa')}
      api={api} projects={data.projects}
      conversation={memoryTargetProject ? null : data.conversations.find(c => c.id === currentConvo)}
      initialProjectId={memoryTargetProject || selectedProject || ''}
      projectOnly={!!memoryTargetProject}
      onMove={moveConversationToProject} onSelectNewProject={setSelectedProject} onRefresh={loadAll}
      onOpenConversation={openConversation} onClose={() => {setMemoryOpen(false);setMemoryTargetProject(null)}}/>}
    {modal?.kind === 'health' ? <HealthDialog provider={modal.item} onClose={() => setModal(null)} notify={notify}/> : modal && <EditorDialog modal={modal} data={data} onClose={() => setModal(null)} onSave={saveEditor}/>}
    {toast && <div role="status" className="fixed bottom-5 right-5 z-[60] max-w-sm rounded-2xl border border-white/15 bg-[#28292c] px-4 py-3 text-sm shadow-xl">{toast}</div>}
  </div>
}

function HealthDialog({ provider, onClose }) {
  const [entries,setEntries]=useState(null)
  useEffect(()=>{api(`/providers/${provider.id}/attempts`).then(setEntries).catch(()=>setEntries([]))},[provider.id])
  return <Modal title={`Saúde: ${provider.name}`} description="Últimas 30 chamadas reais, sem expor credenciais." onClose={onClose} onSubmit={e=>{e.preventDefault();onClose()}} submit="Fechar"><div className="max-h-72 overflow-auto">{entries===null?<p className="text-sm text-muted">Carregando…</p>:entries.length?entries.map((entry,i)=><div key={i} className="flex items-center justify-between gap-3 border-b border-white/10 py-3 text-xs"><span>{dateLabel(entry.created_at,true)}<small className="block text-muted">{entry.http_status?`HTTP ${entry.http_status}`:entry.category||'—'}</small></span><Status value={entry.success?'completed':'failed'}>{entry.success?'Sucesso':'Falhou'}</Status><span>{entry.latency_ms} ms</span></div>):<p className="text-sm text-muted">Nenhum teste ou execução registrada.</p>}</div></Modal>
}
